function checkAchievements(){const milestones=[{at:100,reward:3,label:'First Light'},{at:10000,reward:7,label:'Nebula Prospector'},{at:1000000,reward:15,label:'Star Architect'},{at:100000000,reward:30,label:'Cosmic Tycoon'}];for(const m of milestones){if(s.total>=m.at&&!s.achievements.includes(m.at)){s.achievements.push(m.at);s.gems+=m.reward;toast(`Achievement: ${m.label} · +${m.reward} gems!`);playTone('chest')}}}
function buyUpgrade(id){const u=upgrades.find(x=>x.id===id);if(!u||s.upgrades.includes(id)||s.energy<u.cost)return;s.energy-=u.cost;s.upgrades.push(id);playTone('buy');toast(`${u.name} researched!`);update();queueSave()}
function update(){
 const rate=eps();$('#energy').textContent=fmt(s.energy);$('#gems').textContent=fmt(s.gems);$('#eps').textContent=fmt(rate);$('#panel-eps').textContent=`${fmt(rate)} / SEC`;$('#total').textContent=fmt(s.total);$('#click-power').textContent=fmt(clickPower());
 let rank=0;for(let i=1;i<thresholds.length;i++)if(s.total>=thresholds[i])rank=i;
 const labels=['Core Initiate','Nebula Scout','Star Prospector','Nova Engineer','Galactic Architect','Cosmic Pioneer','Eternal Constellation'];$('#rank').textContent=labels[rank].toUpperCase();$('#level-name').textContent=labels[rank];$('#core-level').textContent=String(rank+1).padStart(2,'0');const next=thresholds[Math.min(rank+1,thresholds.length-1)];const current=thresholds[rank];const pct=rank===thresholds.length-1?100:Math.min(100,(s.total-current)/(next-current)*100);$('#level-progress').style.width=pct+'%';$('#level-next').textContent=rank===thresholds.length-1?'Maximum rank achieved':`Next rank at ${fmt(next)} Energy`;$('#level-sub').textContent=`Lifetime energy: ${fmt(s.total)}${rank===thresholds.length-1?' · MAX RANK':` / ${fmt(next)}`}`;
 const q=Math.min(100,s.runEarned/1000*100);$('#quest-progress').style.width=q+'%';$('#quest-count').textContent=s.quest?'COMPLETE':`${fmt(Math.min(s.runEarned,1000))} / 1,000`;
 const shards=Math.floor(Math.sqrt(s.runEarned/1000000));$('#shards-gain').textContent=fmt(shards);$('#prestige-btn').disabled=shards<1;$('#shard-count').textContent=fmt(s.shards);$('#prestige-count').textContent=fmt(s.prestige);$('#buy-double').disabled=s.double||s.gems<75;$('#buy-double').textContent=s.double?'OWNED':'75 💎';$('#buy-warp').disabled=s.gems<30;$('#buy-loot').disabled=s.gems<20;
 renderGenerators();
}
function openModal(symbol,title,body,confirmText,callback){const modal=$('#modal');modal.innerHTML=`<button class="modal-close" aria-label="Close">✕</button><div class="modal-symbol">${symbol}</div><h2>${title}</h2><p>${body}</p><button class="modal-confirm" id="modal-confirm">${confirmText}</button><button class="modal-secondary" id="modal-cancel">Maybe later</button>`;$('#modal-backdrop').classList.add('open');const close=()=>$('#modal-backdrop').classList.remove('open');$('.modal-close').onclick=close;$('#modal-cancel').onclick=close;$('#modal-confirm').onclick=()=>{close();callback?.()};$('#modal-backdrop').onclick=e=>{if(e.target.id==='modal-backdrop')close()}}
function buyDouble(){if(s.double||s.gems<75)return;s.gems-=75;s.double=true;playTone('buy');toast('Eternal Abundance activated! Permanent ×2');update();queueSave()}
function buyWarp(){if(s.gems<30)return;const amount=eps()*60*60*4;if(amount<=0){toast('Build a generator first to use a Time Warp');return}s.gems-=30;gain(amount);playTone('buy');toast(`Time warp collected ${fmt(amount)} Energy!`);update();queueSave()}
function buyLoot(){if(s.gems<20)return;s.gems-=20;const roll=Math.random();if(roll<.45){const amount=Math.max(100,eps()*300+100);gain(amount);toast(`Capsule: ${fmt(amount)} Energy cache!`)}else if(roll<.75){s.gems+=35;toast('Capsule jackpot! +35 gems 💎')}else{const boost=clickPower()*500;gain(boost);toast(`Capsule: +${fmt(boost)} Energy and a bright idea!`)}playTone('chest');update();queueSave()}
function doPrestige(){const n=Math.floor(Math.sqrt(s.runEarned/1000000));if(!n)return;openModal('✺','Begin a Supernova? ',`This timeline resets: ${fmt(s.energy)} Energy, all generators and research. In exchange, earn ${n} Star Shard${n===1?'':'s'} for a permanent ×${(1+.25*n).toFixed(2)} production multiplier.`, 'REBIRTH NOW',()=>{s.shards+=n;s.prestige++;s.energy=0;s.runEarned=0;s.counts=[0,0,0,0,0,0];s.upgrades=[];s.quest=false;playTone('chest');toast(`Timeline reborn · +${n} Star Shards!`);update();renderUpgrades();queueSave()})}
$('#prestige-btn').onclick=doPrestige;$('#buy-double').onclick=buyDouble;$('#buy-warp').onclick=buyWarp;$('#buy-loot').onclick=buyLoot;

