$('#prestige-btn').onclick=doPrestige;$('#buy-double').onclick=buyDouble;$('#buy-warp').onclick=buyWarp;$('#buy-loot').onclick=buyLoot;

// Tab navigation
$$('.nav-btn').forEach(btn=>btn.onclick=()=>{
  $$('.nav-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  $$('.tab-content').forEach(tab=>tab.classList.remove('active'));
  $(`#tab-${btn.dataset.tab}`).classList.add('active');
  if(btn.dataset.tab==='upgrades')renderUpgrades();
  if(btn.dataset.tab==='generators')renderGenerators();
});

// Purchase mode controls
$$('[data-buy]').forEach(btn=>btn.onclick=()=>{
  $$('[data-buy]').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  buyMode=btn.dataset.buy==='max'?'max':Number(btn.dataset.buy);
  renderGenerators();
});

// Gem pack checkout (simulated; no payment provider or real charge)
$$('[data-pack]').forEach(btn=>btn.onclick=()=>openModal('💎','Confirm gem pack',
  `Add ${Number(btn.dataset.pack).toLocaleString()} gems for ${btn.dataset.price}? This is a simulated checkout—no real payment will be processed.`,
  `ADD ${btn.dataset.pack} GEMS`,()=>{
    s.gems+=Number(btn.dataset.pack);
    playTone('chest');toast(`Checkout complete · +${fmt(Number(btn.dataset.pack))} gems!`);
    update();queueSave();
  }));

// Sound toggle
$('#sound-toggle').onclick=()=>{
  s.sound=!s.sound;
  $('#sound-toggle').textContent=s.sound?'♫':'♩';
  $('#sound-toggle').setAttribute('aria-pressed',String(s.sound));
  if(s.sound)playTone('buy');
  queueSave();
};

// Golden chest
function spawnChest(){
  if($('#chest-layer').querySelector('.chest'))return;
  const chest=document.createElement('button');
  chest.className='chest';chest.type='button';chest.setAttribute('aria-label','Open golden chest');chest.textContent='🎁';
  chest.onclick=()=>{
    const reward=10+Math.floor(Math.random()*16);s.gems+=reward;chest.remove();
    s.chestAt=Date.now()+120000;playTone('chest');toast(`Golden chest! +${reward} gems 💎`);update();queueSave();
  };
  $('#chest-layer').appendChild(chest);setTimeout(()=>{if(chest.isConnected){chest.remove();s.chestAt=Date.now()+90000}},18000);
}

// Offline Energy, production, spawning and saving loop
if(s.last){const elapsed=Math.min(8*60*60,Math.max(0,(Date.now()-s.last)/1000));if(elapsed>5&&eps()>0){const offline=eps()*elapsed;gain(offline);toast(`Welcome back! +${fmt(offline)} offline Energy`)}}
renderGenerators();renderUpgrades();update();
$('#sound-toggle').textContent=s.sound?'♫':'♩';
setInterval(()=>{const now=Date.now(),dt=Math.min(1,(now-lastTick)/1000);lastTick=now;const amount=eps()*dt;if(amount>0)gain(amount);update();if(now>=s.chestAt)spawnChest()},100);
setInterval(queueSave,5000);
window.addEventListener('beforeunload',save);
})();
</script>
</body>
</html>

